import { SUDOKU_SIZE, BOX_SIZE } from '@sudoku/constants';

function isValidGridSize(grid) {
	return Array.isArray(grid) && grid.length === SUDOKU_SIZE && grid.every(r => Array.isArray(r) && r.length === SUDOKU_SIZE);
}

function isValidCandidatesSize(candidatesMap) {
	return (
		Array.isArray(candidatesMap) &&
		candidatesMap.length === SUDOKU_SIZE &&
		candidatesMap.every(r => Array.isArray(r) && r.length === SUDOKU_SIZE)
	);
}

function formatCell(r, c) {
	// 用户可读：1-based
	return `第${r + 1}行第${c + 1}列`;
}

function boxIndexOf(r, c) {
	return Math.floor(r / BOX_SIZE) * BOX_SIZE + Math.floor(c / BOX_SIZE);
}

function getRowCells(row) {
	return Array.from({ length: SUDOKU_SIZE }, (_, c) => [row, c]);
}

function getColCells(col) {
	return Array.from({ length: SUDOKU_SIZE }, (_, r) => [r, col]);
}

function getBoxCells(boxIdx) {
	const cells = [];
	const startRow = Math.floor(boxIdx / BOX_SIZE) * BOX_SIZE;
	const startCol = (boxIdx % BOX_SIZE) * BOX_SIZE;
	for (let r = startRow; r < startRow + BOX_SIZE; r++) {
		for (let c = startCol; c < startCol + BOX_SIZE; c++) {
			cells.push([r, c]);
		}
	}
	return cells;
}

class ExplanationContext {
	/**
	 * @param {number[][]} grid
	 * @param {number[][][]} candidatesMap
	 */
	constructor(grid, candidatesMap) {
		this.grid = grid;
		this.candidatesMap = candidatesMap;
	}

	isEmptyCell(r, c) {
		return this.grid[r][c] === 0;
	}

	getCandidates(r, c) {
		const cands = this.candidatesMap[r][c];
		return Array.isArray(cands) ? cands : [];
	}

	formatCell(r, c) {
		return formatCell(r, c);
	}

	formatUnit(unitType, unitIndex) {
		if (unitType === 'row') return `第${unitIndex + 1}行`;
		if (unitType === 'col') return `第${unitIndex + 1}列`;
		if (unitType === 'box') return `第${unitIndex + 1}宫`;
		return '';
	}
}

class ExplainerRule {
	constructor(name) {
		this.name = name;
	}

	/**
	 * @param {ExplanationContext} _ctx
	 * @returns {{strategy: string, message: string}[]}
	 */
	generate(_ctx) {
		throw new Error('Implement generate(ctx)');
	}
}

class NakedSingleExplainer extends ExplainerRule {
	constructor() {
		super('NakedSingle');
	}

	generate(ctx) {
		const out = [];
		for (let r = 0; r < SUDOKU_SIZE; r++) {
			for (let c = 0; c < SUDOKU_SIZE; c++) {
				if (!ctx.isEmptyCell(r, c)) continue;
				const cands = ctx.getCandidates(r, c);
				if (cands.length === 1) {
					const v = cands[0];
					out.push({
						strategy: this.name,
						message: `${ctx.formatCell(r, c)} 只剩一个候选数 ${v}（显性单值），因此该格必须为 ${v}。`
					});
				}
			}
		}
		return out;
	}
}

class HiddenSingleExplainer extends ExplainerRule {
	constructor() {
		super('HiddenSingle');
	}

	generate(ctx) {
		const out = [];
		const units = [
			{ type: 'row', getter: getRowCells },
			{ type: 'col', getter: getColCells },
			{ type: 'box', getter: getBoxCells },
		];

		for (const unit of units) {
			for (let i = 0; i < SUDOKU_SIZE; i++) {
				const cells = unit.getter(i);
				/** @type {Record<number, Array<[number, number]>>} */
				const positionsByValue = {};

				for (const [r, c] of cells) {
					if (!ctx.isEmptyCell(r, c)) continue;
					const cands = ctx.getCandidates(r, c);
					for (const v of cands) {
						if (!positionsByValue[v]) positionsByValue[v] = [];
						positionsByValue[v].push([r, c]);
					}
				}

				for (const key of Object.keys(positionsByValue)) {
					const v = Number(key);
					const positions = positionsByValue[v];
					if (positions.length !== 1) continue;
					const [r, c] = positions[0];
					const cands = ctx.getCandidates(r, c);
					if (cands.length <= 1) continue;

					out.push({
						strategy: this.name,
						message: `在${ctx.formatUnit(unit.type, i)}中，数字 ${v} 只出现在 ${ctx.formatCell(r, c)} 的候选列表里（隐性单值），因此该格必须为 ${v}。`
					});
				}
			}
		}

		return out;
	}
}

class NakedPairExplainer extends ExplainerRule {
	constructor() {
		super('NakedPair');
	}

	generate(ctx) {
		const out = [];
		const units = [
			{ type: 'row', getter: getRowCells },
			{ type: 'col', getter: getColCells },
			{ type: 'box', getter: getBoxCells },
		];

		for (const unit of units) {
			for (let i = 0; i < SUDOKU_SIZE; i++) {
				const cells = unit.getter(i);
				/** @type {Map<string, Array<[number, number]>>} */
				const pairPositions = new Map();

				for (const [r, c] of cells) {
					if (!ctx.isEmptyCell(r, c)) continue;
					const cands = ctx.getCandidates(r, c);
					if (cands.length !== 2) continue;
					const key = `${cands[0]},${cands[1]}`;
					if (!pairPositions.has(key)) pairPositions.set(key, []);
					pairPositions.get(key).push([r, c]);
				}

				for (const [key, positions] of pairPositions.entries()) {
					if (positions.length !== 2) continue;
					const [v1, v2] = key.split(',').map(Number);
					const [aR, aC] = positions[0];
					const [bR, bC] = positions[1];

					// 找到该 unit 内其它仍包含 v1/v2 的格子（用于说明“可以排除谁”）
					const affected = [];
					for (const [r, c] of cells) {
						if ((r === aR && c === aC) || (r === bR && c === bC)) continue;
						if (!ctx.isEmptyCell(r, c)) continue;
						const cands = ctx.getCandidates(r, c);
						if (cands.includes(v1) || cands.includes(v2)) affected.push([r, c]);
					}

					const pairText = `{${v1}, ${v2}}`;
					const base = `在${ctx.formatUnit(unit.type, i)}中，${ctx.formatCell(aR, aC)} 与 ${ctx.formatCell(bR, bC)} 的候选都恰好是 ${pairText}（显性对）。因此在该单位的其它空格中，${v1} 和 ${v2} 都不能再出现。`;

					if (affected.length === 0) {
						out.push({ strategy: this.name, message: base });
						continue;
					}

					const affectedText = affected.map(([r, c]) => ctx.formatCell(r, c)).join('、');
					out.push({
						strategy: this.name,
						message: `${base} 受影响的格子包括：${affectedText}。`
					});
				}
			}
		}

		return out;
	}
}

class ExplanationGenerator {
	constructor(rules) {
		this.rules = rules;
	}

	/**
	 * @param {ExplanationContext} ctx
	 * @param {{strategiesToUse?: string[], maxExplanations?: number}} options
	 */
	run(ctx, options = {}) {
		const strategiesToUse = Array.isArray(options.strategiesToUse) ? options.strategiesToUse : null;
		const maxExplanations = Number.isFinite(options.maxExplanations) ? options.maxExplanations : Infinity;

		/** @type {{strategy: string, message: string}[]} */
		const out = [];

		for (const rule of this.rules) {
			if (strategiesToUse && !strategiesToUse.includes(rule.name)) continue;
			for (const item of rule.generate(ctx)) {
				out.push(item);
				if (out.length >= maxExplanations) return out;
			}
		}

		return out;
	}
}

const DEFAULT_GENERATOR = new ExplanationGenerator([
	new NakedSingleExplainer(),
	new HiddenSingleExplainer(),
	new NakedPairExplainer(),
]);

/**
 * 生成可读的推理解释文本。
 *
 * 输入可以是：
 * 1) explain(grid, candidatesMap, options)
 * 2) explain({ grid, candidatesMap, strategiesToUse?, maxExplanations? })
 *
 * @param {number[][] | {grid: number[][], candidatesMap: number[][][], strategiesToUse?: string[], maxExplanations?: number}} gridOrPayload
 * @param {number[][][]=} candidatesMap
 * @param {{strategiesToUse?: string[], maxExplanations?: number}=} options
 * @returns {string[]}
 */
export function explain(gridOrPayload, candidatesMap, options) {
	let grid;
	let cmap;
	let opts;

	if (gridOrPayload && typeof gridOrPayload === 'object' && !Array.isArray(gridOrPayload) && gridOrPayload.grid) {
		grid = gridOrPayload.grid;
		cmap = gridOrPayload.candidatesMap;
		opts = {
			strategiesToUse: gridOrPayload.strategiesToUse,
			maxExplanations: gridOrPayload.maxExplanations,
		};
	} else {
		grid = gridOrPayload;
		cmap = candidatesMap;
		opts = options || {};
	}

	if (!isValidGridSize(grid)) {
		throw new Error('explain(): invalid grid size, expected 9x9 number[][]');
	}
	if (!isValidCandidatesSize(cmap)) {
		throw new Error('explain(): invalid candidatesMap size, expected 9x9 number[][][]');
	}

	const ctx = new ExplanationContext(grid, cmap);
	const items = DEFAULT_GENERATOR.run(ctx, opts);
	return items.map(i => i.message);
}

// 额外导出：方便前端拿到更结构化的信息（如果以后需要高亮格子）
export function explainDetailed(gridOrPayload, candidatesMap, options) {
	let grid;
	let cmap;
	let opts;

	if (gridOrPayload && typeof gridOrPayload === 'object' && !Array.isArray(gridOrPayload) && gridOrPayload.grid) {
		grid = gridOrPayload.grid;
		cmap = gridOrPayload.candidatesMap;
		opts = {
			strategiesToUse: gridOrPayload.strategiesToUse,
			maxExplanations: gridOrPayload.maxExplanations,
		};
	} else {
		grid = gridOrPayload;
		cmap = candidatesMap;
		opts = options || {};
	}

	if (!isValidGridSize(grid)) {
		throw new Error('explainDetailed(): invalid grid size, expected 9x9 number[][]');
	}
	if (!isValidCandidatesSize(cmap)) {
		throw new Error('explainDetailed(): invalid candidatesMap size, expected 9x9 number[][][]');
	}

	const ctx = new ExplanationContext(grid, cmap);
	return DEFAULT_GENERATOR.run(ctx, opts);
}
